60:  function primary() {
61:    const token = take();
62:    if (token.type === 'number') return { type: 'number', value: token.value };
63:    if (token.type === 'identifier') {
64:      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
65:      take();
66:      const args = [];
67:      if (!is(')')) {
68:        args.push(comparison());
69:        while (is(',')) {
70:          take();
71:          args.push(comparison());
72:        }
73:      }
