const { evaluate, ExprError } = require('./src/index');
const col = (s, v) => { try { evaluate(s, v); return 'no error'; } catch (e) { return e instanceof ExprError ? e.column : e; } };
const out = {
  negPow: evaluate('-2 ** 2'), powNeg: evaluate('2 ** -1'), powRight: evaluate('2 ** 3 ** 2'),
  mulNeg: evaluate('2 * -3 ** 2'), floordivF: evaluate('1 // 0.1'), modF: evaluate('-1 % 0.3'),
  zeroFloor: Object.is(evaluate('-0.0 // 5'), 0), zeroMod: Object.is(evaluate('-6 % 3'), 0),
  infMod: evaluate('1e999 % 2'), negInfDiv: evaluate('-5 // 1e999'), onePowInf: evaluate('1 ** 1e999'),
  chain: evaluate('1 < 2 < 3'), chainFalse: evaluate('3 > 2 > 1 == 1'), boolArith: evaluate('(1 < 2) + 1'),
  boolEq: evaluate('(1 < 2) == 1'), maxBool: evaluate('max(1 < 2, 0)'), minNaN: evaluate('min(1, x)', { x: NaN }),
  absBool: evaluate('abs(-(2 > 1))'), unaryRun: evaluate('- - -3'),
  wsCol: col('1 +   $'), eofCol: col('1 +  '), unkFn: col('1 + foo(2)'), absArity: col('  abs(1, 2)'),
  minEmpty: col('min()'), unkVar: col('a + b', { a: 1 }), divZero: col('1 + 4 // 0'), trailing: col('min(1,)'),
};
const reads = [];
const vars = { get a() { reads.push('a'); return 5; }, get b() { reads.push('b'); return 1; }, get c() { reads.push('c'); return 9; } };
out.shortCircuit = [evaluate('a < b < c', vars), reads.join('')];
const n = 200000;
let t = Date.now();
out.longSum = evaluate(Array.from({ length: n }, (_, i) => (i % 2 ? '-' : '') + '1').join(' + '));
out.longChain = evaluate(Array.from({ length: n }, (_, i) => String(i)).join(' < '));
out.longSigns = evaluate('-'.repeat(n) + '1');
out.ms = Date.now() - t;
console.log(out);
